python3 - <<'EOF'
import json
d=json.load(open('.omgithub/conversation.json'))
msgs=d['messages']
print(len(msgs))
for m in msgs[-16:]:
    print('===',m['id'],m.get('type'),m.get('time',{}).get('created'))
    txt=m.get('text') or ''
    if txt: print(txt[:1200])
    for c in m.get('content',[]) if isinstance(m.get('content'),list) else []:
        t=c.get('type')
        if t=='text': print('[text]',c.get('text','')[:1500])
        elif t=='tool':
            print('[tool]',c.get('name'), str(c.get('state',{}).get('input'))[:800])
            content=c.get('state',{}).get('content')
            if content: print('[out]',str(content)[:1000])
        elif t=='reasoning': print('[reason]',c.get('text','')[:800])
EOF

